const fs = require('node:fs');
const path = require('node:path');

const pngBase64 = '';

const directory = process.env.MAKEFUN_OUTPUT_DIR ?? './out';
const destination = path.join(directory, 'entry.png');

fs.mkdirSync(directory, { recursive: true });

const frontPage = Buffer.from(pngBase64, 'base64');
fs.writeFileSync(destination, frontPage);
console.log(`Wrote ${destination} (${frontPage.length} bytes)`);
